using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using OwnLabView;
class ReopenLibraries {
 [STAThread]static int Main(string[] a){typeof(Storage).GetField("Root").SetValue(null,a[0]);object app=null,project=null,context=null;var refs=new List<object>();var checks=new List<object>();try{using(var lease=new NiSessionLease()){app=Activator.CreateInstance(Type.GetTypeFromProgID("LabVIEW.Application",true));lease.Attached();foreach(string file in new[]{"library.json","nested.json","copied.json"}){var report=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(Path.Combine(a[1],file))));string path=Data.Text(report,"library_path");Libraries.Validate(path);project=LabView.Invoke(app,"NewProject",BindingFlags.InvokeMethod);context=LabView.Invoke(project,"Application",BindingFlags.GetProperty);object lib=LabView.Invoke(context,"OpenLibrary",BindingFlags.InvokeMethod,path);refs.Add(lib);foreach(var raw in Data.Array(report["native_members"])){var row=Data.Map(raw);if(!row.ContainsKey("vi_type")||Convert.ToInt32(row["vi_type"])!=1)continue;string viPath=Data.Text(row,"path");object vi=LabView.Invoke(context,"GetVIReference",BindingFlags.InvokeMethod,viPath,"",false,0);refs.Add(vi);if(Convert.ToInt32(LabView.Invoke(vi,"ExecState",BindingFlags.GetProperty))!=1)throw new IOException("Reopened library method not compiled: "+viPath);string name=Convert.ToString(LabView.Invoke(vi,"Name",BindingFlags.GetProperty));if(name!=Data.Text(row,"qualified_name"))throw new IOException("Qualified name changed after reopen.");if(Path.GetFileName(viPath).StartsWith("Body_")){LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"A",2.0);LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"B",3.0);LabView.Invoke(vi,"Run",BindingFlags.InvokeMethod,false);if(Convert.ToDouble(LabView.Invoke(vi,"GetControlValue",BindingFlags.InvokeMethod,"Sum"))!=5)throw new IOException("Copied library addition differs.");checks.Add(new{file,path=viPath,passed=true,finite_result=5});}else checks.Add(new{file,path=viPath,passed=true,compiled=true});}Libraries.Validate(path);for(int i=refs.Count-1;i>=0;i--)LabView.Release(refs[i]);refs.Clear();LabView.Release(context);context=null;LabView.Invoke(project,"Close",BindingFlags.InvokeMethod);LabView.Release(project);project=null;}}
 Storage.WriteNew(Path.Combine(a[1],"library-runtime-"+a[2]+".json"),new{passed=true,checks,window_operations_used=false,source_files_unchanged=true});return 0;}catch(Exception e){Storage.WriteNew(Path.Combine(a[1],"library-failure-"+a[2]+".json"),new{error=e.ToString(),checks});return 1;}finally{for(int i=refs.Count-1;i>=0;i--)LabView.Release(refs[i]);LabView.Release(context);LabView.Release(project);LabView.Release(app);}}
}
